const test=require('node:test'),assert=require('node:assert/strict'),fs=require('node:fs'),path=require('node:path');const{setup}=require('./baseline-harness.cjs');const{scalar}=require('./harness.cjs');
const migrationDir=path.join(__dirname,'../../../supabase/migrations');const install=fs.readFileSync(path.join(migrationDir,fs.readdirSync(migrationDir).find(f=>f.endsWith('_provider_snapshot_tiered_retention.sql'))),'utf8');const rollback=fs.readFileSync(path.join(__dirname,'rollback.sql'),'utf8');
async function reject(db,sql,re){await assert.rejects(()=>db.exec(sql),re);await db.exec('rollback');}
test('rebased install refuses unknown dependency code and rollback preserves both reviewed fixes exactly',async()=>{const db=await setup({protocol:false});try{const signatures=['private.provider_snapshot_dependency_token(jsonb)','private.provider_snapshot_run_claimed(text)'];const values=async()=>(await db.query('select oid::regprocedure::text signature,md5(prosrc)body from pg_proc where oid=any($1::regprocedure[])order by signature',[signatures])).rows;const before=await values();const tokenValue=()=>scalar(db,"select private.provider_snapshot_dependency_token('{}'::jsonb)");const dependencyBefore=await tokenValue();assert.deepEqual(before.map(x=>x.body),['ccf807a978ba7f0d3cb9f527dad6c5d4','6a5a418cb1fabf6fdbe6b7c59ebcfcd9']);await db.exec("create or replace function private.provider_snapshot_dependency_token(p_target jsonb)returns text language sql stable security invoker set search_path=''as $$select md5('unknown:'||p_target::text)$$");await reject(db,install,/before_function_drift/);await db.exec(fs.readFileSync(path.join(__dirname,'dependency-token-after.sql'),'utf8'));await db.exec(install);assert.deepEqual(await values(),before);assert.equal(await tokenValue(),dependencyBefore);await db.exec(rollback);assert.deepEqual(await values(),before);assert.equal(await tokenValue(),dependencyBefore);await db.exec(install);assert.deepEqual(await values(),before);assert.equal(await tokenValue(),dependencyBefore);}finally{await db.close()}});
test('exact metadata installer/replay/rollback/reinstall preserve derived heads and retirement audit',async()=>{const db=await setup({protocol:false});try{await db.exec("insert into public.ar_config_targets values('AR','IN','RELEASE','INR','印度','Asia/Kolkata');insert into public.dashboard_platform_team_map values('AR','IN','RELEASE','Release','M8','IN','印度',true)");const t=await scalar(db,"select to_jsonb(t)from private.provider_snapshot_native_catalog()t where source_name='RELEASE'");await db.query('select private.provider_snapshot_register_target($1)',[t]);const q={action:'aggregate',view:'providers',platformId:t.id,startAt:'2026-10-10T18:30:00.000000Z',endAt:'2026-10-11T18:30:00.000000Z',direction:'charge',status:'all',currency:'INR'};const id=await scalar(db,"select private.provider_snapshot_enqueue($1,$2,'orders')",[t,q]);const j=await scalar(db,"select private.provider_snapshot_claim('release',120)");const now=new Date().toISOString();const payload={version:1,platform:{id:t.id,source:t.source,sourceName:t.source_name,scopeGroup:t.scope_group,currency:t.currency,timezone:t.timezone},startAt:q.startAt,endAt:q.endAt,summary:[],groups:{provider:[]},rows:[]};assert.equal((await scalar(db,'select private.provider_snapshot_complete($1,$2,$3,$4,$5)',[j.jobId,j.runId,j.fence,payload,{computationComplete:true,upstreamComplete:false,sourceWatermark:{kind:'synthetic'},sourceReadStartedAt:now,sourceReadCompletedAt:now}])).published,true);const before=(await db.query('select *from private.provider_snapshot_heads')).rows;
await db.exec(install);await db.exec(install);assert.equal(Number(await scalar(db,"select jobs from private.provider_snapshot_storage_usage where storage_class='history'")),1);assert.deepEqual((await db.query('select *from private.provider_snapshot_heads')).rows,before);const cohort=await scalar(db,"insert into private.provider_snapshot_cohorts(lane,local_date,cutoff,supplement_pass,roster_token,targets,status)values('current','2026-10-10','2026-10-10T05:00:00Z',0,'audit',$1,'obsolete')returning id",[[t]]);await db.query("insert into private.provider_snapshot_retired_cohorts values($1,gen_random_uuid(),clock_timestamp(),0,0)",[cohort]);await db.exec(rollback);await db.exec(rollback);assert.equal(await scalar(db,"select count(*)::int from private.provider_snapshot_retired_cohorts"),1);assert.deepEqual((await db.query('select *from private.provider_snapshot_heads')).rows,before);await db.exec(install);assert.equal(await scalar(db,'select private.provider_snapshot_kernel_contract_current()'),true);assert.deepEqual((await db.query('select *from private.provider_snapshot_heads')).rows,before);assert.equal(await scalar(db,'select id::text from private.provider_snapshot_jobs'),id);}finally{await db.close()}});
test('installer rejects changed baseline grants/extra overload and rollback rejects disabled accounting trigger',async()=>{const db=await setup({protocol:false});try{await db.exec('grant execute on function private.provider_snapshot_enqueue(jsonb,jsonb,text,timestamptz)to authenticated');await reject(db,install,/before_function_drift/);await db.exec('revoke execute on function private.provider_snapshot_enqueue(jsonb,jsonb,text,timestamptz)from authenticated');await db.exec('create function private.provider_snapshot_enqueue(text)returns integer language sql as $$select 1$$');await reject(db,install,/before_function_drift/);await db.exec('drop function private.provider_snapshot_enqueue(text)');await db.exec(install);await db.exec('alter table private.provider_snapshot_jobs disable trigger provider_snapshot_account_jobs');await reject(db,install,/installed_table_drift/);await reject(db,rollback,/rollback_before_table_drift/);assert.ok(await scalar(db,"select to_regclass('private.provider_snapshot_storage_usage')::text"));}finally{await db.close()}});
test('all quota side effects roll back with writes, and truncate cannot desynchronize accounting',async()=>{const db=await setup({protocol:false});try{await db.exec(install);await db.exec('begin');await db.exec("insert into private.provider_snapshot_jobs(request_key,target,request,component,platform_id,window_from,window_to,dependency_token)values('{}','{\"scope_group\":\"IN\",\"timezone\":\"Asia/Kolkata\"}','{}','orders',gen_random_uuid(),'2026-10-10T18:30:00Z','2026-10-10T19:30:00Z','synthetic')");assert.equal(Number(await scalar(db,"select jobs from private.provider_snapshot_storage_usage where storage_class='hot'")),1);await db.exec('rollback');assert.equal(Number(await scalar(db,"select jobs from private.provider_snapshot_storage_usage where storage_class='hot'")),0);await assert.rejects(()=>db.exec('truncate private.provider_snapshot_jobs cascade'),/snapshot_accounting_requires_bounded_delete/);}finally{await db.close()}});
